python3 -c "
import json
l4_outputs = []
with open('/logs/agent/opencode.txt') as f:
    for line in f:
        if '330330330aa' in line:
            obj = json.loads(line)
            st = obj.get('part', {}).get('state', {})
            out = st.get('output', '')
            if 'Screen (64 rows x 64 hex cells):' in out:
                l4_outputs.append((st.get('input', {}), out))

print('Total L4 game_act outputs:', len(l4_outputs))
for i, (inp, out) in enumerate(l4_outputs):
    lines = out.split('Screen (64 rows x 64 hex cells):\n')[1].strip().split('\n')[:64]
    # find hazard '99999'
    h_col = -1
    for r_idx, l in enumerate(lines):
        if '99999' in l:
            h_col = (l.find('99999') - 7) // 5
            h_row = (r_idx - 10) // 5
            break
    # find P
    p_pos = None
    k_pos = None
    for r in range(10):
        for c in range(10):
            block = ''.join(lines[10 + r*5 + dr][7 + c*5 : 7 + (c+1)*5] for dr in range(5))
            if 'c' in block: p_pos = (r, c)
            top_row = lines[10 + r*5][7 + c*5 : 7 + (c+1)*5]
            if '8' in block and top_row == '00800': k_pos = (r, c)
    print(f'L4 Step {i}: input={inp} -> P={p_pos}, K={k_pos}, Hazard=({h_row},{h_col})')
"

